var wf_customer_id_value = Context.getVariable("customer_id");
Context.setVariable("wf_customer_id", wf_customer_id_value);

var wf_customer_fname_value = Context.getVariable("customer_fname");
Context.setVariable("wf_customer_fname", wf_customer_fname_value);

var wf_customer_lname_value = Context.getVariable("customer_lname");
Context.setVariable("wf_customer_lname", wf_customer_lname_value);

var wf_customer_email_value = Context.getVariable("customer_email");
Context.setVariable("wf_customer_email", wf_customer_email_value);

// random number between 100000 and 999999 to avoid leading zeros
let oneTimePin = String(Math.floor(Math.random() * 900000) + 100000);

Context.setVariable('One_Time_Pin', oneTimePin);

Context.setVariable('SMS_Number', 
    Context.getVariable('phone_number').replace(/\D/g, ""));

Context.setVariable('SMS_Message',
    'Your one-time authentication PIN is ' + oneTimePin);
